with open('/tmp/hx9915_STOCK.rom', 'rb') as f:
    data = f.read()

# Let's search the whole ROM for UTF-16LE 'audio' patterns
# In UTF-16LE, ASCII chars are interleaved with 0x00
# But also UEFI strings might start with a length byte

# Pattern: 'A' 'u' 'd' 'i' 'o' as UTF-16LE = 41 00 75 00 64 00 69 00 6F 00
# Let me search with various case combinations  
import re

# First, search the raw bytes with a wildcard for the null byte
for term in ['Audio', 'audio', 'AUDIO', 'BCLK', 'bclk', 'Bclk', 'BCLK', 'HDA']:
    found = False
    for i in range(len(data) - 20):
        match = True
        for j, c in enumerate(term):
            # UTF-16LE: char byte at position j*2, null byte at j*2+1
            idx = i + j * 2
            if idx >= len(data):
                match = False
                break
            if data[idx] != ord(c):
                match = False
                break
            if idx + 1 < len(data) and data[idx+1] != 0x00:
                match = False
                break
        if match:
            print('UTF-16LE \"%s\" at 0x%x (context: %s)' % (term, i, data[max(0,i-4):i+len(term)*2+4].hex()))
            found = True
    if not found:
        print('UTF-16LE \"%s\" not found' % term)

print()
# Also try UTF-16LE with preceding length byte (prefix length = strlen*2)
for term in ['Audio', 'audio', 'BCLK', 'bclk']:
    found = False
    for i in range(len(data) - 20):
        # Check for length-prefixed string: length_byte = len(term)*2
        if i > 0 and data[i-1] == len(term) * 2:
            match = True
